con:config.script:
testRunner.testCase.testSuite.project.setPropertyValue("projectLevelVariable", "Brave");

testRunner.testCase.testSuite.setPropertyValue("testSuitLevelVariable", "I");

testRunner.testCase.setPropertyValue("testCaseLevelVariable", "Am");

testRunner.testCase.getTestStepByName("Properties").setPropertyValue("testStepLevelVariable", "Kk");

def projectLevelVariable = testRunner.testCase.testSuite.project.getPropertyValue("projectLevelVariable");
def testSuiteLevelVariable = testRunner.testCase.testSuite.getPropertyValue("testSuitLevelVariable"); 
def testCaseVariable = testRunner.testCase.getPropertyValue("testCaseLevelVariable");
def testStepVariable = testRunner.testCase.getTestStepByName("Properties").getPropertyValue("testStepLevelVariable");


log.info("Project Level Variable: " + projectLevelVariable);
log.info("Test Suite Level Variable: " + testSuiteLevelVariable);
log.info("Test Case Variable: " + testCaseVariable);
log.info("Test Step Variable: " + testStepVariable);

testRunner.testCase.testSuite.project.addProperty("countryNameProjectLevel");
testRunner.testCase.testSuite.addProperty("countryNameTestSuiteLevel");
testRunner.testCase.addProperty("countryNameTestCaseLevel");
testRunner.testCase.getTestStepByName("Properties").addProperty("countryNameTestStepLevel");

testRunner.testCase.testSuite.project.removeProperty("countryNameProjectLevel");
testRunner.testCase.testSuite.removeProperty("countryNameTestSuiteLevel");
testRunner.testCase.removeProperty("countryNameTestCaseLevel");
testRunner.testCase.getTestStepByName("Properties").removeProperty("countryNameTestStepLevel");

testRunner.testCase.properties.each
{
	key,value -> log.info("Variable from for loop: " + testRunner.testCase.getPropertyValue(key));

}

def response = testRunner.testCase.getTestStepByName('GetCountryISOCode').getPropertyValue("response");
def responseValue = new XmlSlurper().parseText(response).text();
log.info(responseValue);

testRunner.testCase.getTestStepByName("Properties").setPropertyValue("countryISOCodeGroovy", responseValue);

class Hello
{
	def log;
	def context;
	def testRunner;

	def Hello (log, context, testRunner)
	{
		this.log = log;
		this.context = context;
		this.testRunner = testRunner;
	}
	def sayHello(String name)
	{
		log.info("Your name is: " + name);
	}	
}

context.setProperty("obj", new Hello(log,context,testRunner));
//context.obj.sayHello("KC");

def testStep = testRunner.testCase.getTestStepByName("Groovy Practice Script");
testStep.run(testRunner,context);
context.obj.sayHello("Kishan Chandrakant Patel")

def na = context.expand('${#project#projectName}');
log.info("Kishan" + na);

def testStepFromOtherTestCase = testRunner.testCase.testSuite.project.testSuites["Country Info SOAP Requests TestSuite1"].testCases["Groovy Practice"].getTestStepByName("Groovy Practice Script");
testStepFromOtherTestCase.run(testRunner, context);
context.obj.sayHello("Hey How's Going?");

def testStep = testRunner.testCase.testSuite.project.testSuites["Country Info SOAP Requests TestSuite1"].testCases["TestCase Transfer Property"].getTestStepByName("CountryISOCode - Request 1");
def response = testStep.run(testRunner, context);
log.info("The response status: " + response.getStatus().toString());

def tc = testRunner.testCase.testSuite.testCases["TestCase Transfer Property"];
def tcStatus = tc.run(null, false).getStatus().toString();
log.info("Status of response: " + tcStatus);

def tcList = context.testCase.testSuite.getTestCaseList();
tcList.each
{
	log.info(it.name);
}

log.info("This TC name: " + testRunner.testCase.name);

