log.info(getSetupScriptOfTestSuite);

def getTearDownScriptOfTestSuite = testRunner.testCase.testSuite.project.testSuites["Country Info SOAP Requests TestSuite1"].getTearDownScript();
log.info(getTearDownScriptOfTestSuite);

testRunner.testCase.testSuite.testCases["Setup and TearDown Script Using Groovy"].setSetupScript('log.info("Setup script is set by Groovy Script")');
testRunner.testCase.testSuite.testCases["Setup and TearDown Script Using Groovy"].setTearDownScript('log.info("TearDown script is set by Groovy Script")');
testRunner.testCase.testSuite.project.workspace.projects["ReqRes REST Project"].testSuites["ReqRes TestSuit1"].setSetupScript('log.info("Setup script is set by Groovy Script")');
testRunner.testCase.testSuite.project.workspace.projects["ReqRes REST Project"].testSuites["ReqRes TestSuit1"].setTearDownScript('log.info("TearDown script is set by Groovy Script")');

