testStepFromOtherTestSuite.run(testRunner, context);
context.obj.sayHello("Hey, going awesome");

def tc = testRunner.testCase.testSuite.project.testSuites["Country Info SOAP Requests TestSuite1"].testCases["TestCase Transfer Property"];
